// Created: 2026-09-25

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import path from "node:path";

// The cookbook sidebar comes from meta.json; the index page's cards are
// hand-written MDX (kept static so the Markdown twin agents read still lists
// every recipe). The 2026-09-25 QA found the index at 6 of 8 recipes while the
// sidebar and home said 8. This pins the two to each other: same pages, same
// order, same titles.
const DIR = path.join(process.cwd(), "content/docs/cookbook");

function frontmatterTitle(file: string): string {
  const m = readFileSync(file, "utf8").match(/^title:\s*"?(.+?)"?\s*$/m);
  if (!m) throw new Error(`no title in ${file}`);
  return m[1];
}

function cardsUnder(heading: string): { title: string; href: string }[] {
  const text = readFileSync(path.join(DIR, "index.mdx"), "utf8");
  const start = text.indexOf(`## ${heading}`);
  expect(start, `index.mdx has a "## ${heading}" section`).toBeGreaterThan(-1);
  const block = text.slice(start, text.indexOf("</Cards>", start));
  return [...block.matchAll(/<Card title="([^"]+)" href="([^"]+)"/g)].map((m) => ({
    title: m[1],
    href: m[2],
  }));
}

function sidebar(dir: string, stopAt?: string): string[] {
  const meta = JSON.parse(readFileSync(path.join(dir, "meta.json"), "utf8")) as {
    pages: string[];
  };
  const end = stopAt ? meta.pages.indexOf(stopAt) : -1;
  return (end < 0 ? meta.pages : meta.pages.slice(0, end)).filter(
    (p) => !p.startsWith("---") && !p.startsWith("..."),
  );
}

describe("cookbook index matches the sidebar", () => {
  it("lists every workflow recipe, in sidebar order, under its page title", () => {
    const pages = sidebar(DIR, "---By Role---");
    expect(pages.length).toBeGreaterThanOrEqual(8);
    expect(cardsUnder("Workflows")).toEqual(
      pages.map((slug) => ({
        title: frontmatterTitle(path.join(DIR, `${slug}.mdx`)),
        href: `/docs/cookbook/${slug}`,
      })),
    );
  });

  it("lists every role page, in sidebar order, under its page title", () => {
    const rolesDir = path.join(DIR, "roles");
    expect(cardsUnder("By Role")).toEqual(
      sidebar(rolesDir).map((slug) => ({
        title: frontmatterTitle(path.join(rolesDir, `${slug}.mdx`)),
        href: `/docs/cookbook/roles/${slug}`,
      })),
    );
  });
});
